  for (const file of generated) {
    const fullPath = join(cwd, file.path);
    if (!existsSync(fullPath)) {
      results.push({
        file: file.path,
        tool: file.tool,
        status: "added",
        linesAdded: file.content.split("\n").length,
        linesRemoved: 0,
      });
    } else {
      const existing = readFileSync(fullPath, "utf-8");
      if (existing === file.content) {
        results.push({
          file: file.path,
          tool: file.tool,
          status: "unchanged",
          linesAdded: 0,
          linesRemoved: 0,
        });
      } else {
        const diff = countDiff(existing.split("\n"), file.content.split("\n"));
        results.push({
          file: file.path,
          tool: file.tool,
          status: "modified",
          linesAdded: diff.added,
          linesRemoved: diff.removed,
        });
      }
    }
  }
  const targetFiles = new Set(generated.map((f) => f.path));
  const knownFiles = [
    "CLAUDE.md",
    ".cursorrules",
    ".github/copilot-instructions.md",
    ".windsurfrules",
    ".clinerules",
    "AGENTS.md",
    ".aider.conf.yml",
  ];
  for (const knownFile of knownFiles) {
    if (!targetFiles.has(knownFile) && existsSync(join(cwd, knownFile))) {
      const content = readFileSync(join(cwd, knownFile), "utf-8");
      results.push({
        file: knownFile,
        tool: "unknown",
        status: "deleted",
        linesAdded: 0,
        linesRemoved: content.split("\n").length,
      });
    }
  }
  return results;
}
